<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Driven;

use Override;
use Throwable;
use Civi\Lughauth\Features\Access\UserGroupMembership\Infrastructure\Connector\Pdo\UserGroupMembershipPdoConnector;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipReadGateway;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipSlide;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipFilter;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipCursor;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembershipRef;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembership;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserGroupMembershipReadRepositoryAdapter implements UserGroupMembershipReadGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly UserGroupMembershipPdoConnector $conn,
    ) {
    }
    #[Override]
    public function resolve(UserGroupMembershipRef $ref): ?UserGroupMembership
    {
        if ($ref instanceof UserGroupMembership) {
            return $ref;
        } elseif (!$ref->_private_resolve) {
            $ref->_private_resolve = $this->conn->retrieve(new UserGroupMembershipFilter(uids: [ $ref->uid() ]));
        }
        return $ref->_private_resolve;
    }
    #[Override]
    public function list(?UserGroupMembershipFilter $filter = null, ?UserGroupMembershipCursor $cursor = null): UserGroupMembershipSlide
    {
        $this->logDebug("List for User group membership on adapter ");
        $span = $this->startSpan("List for User group membership on adapter");
        try {
            $values = $this->conn->list($filter, $cursor);
            $last = end($values);
            return new UserGroupMembershipSlide(function (UserGroupMembershipFilter $slide, ?UserGroupMembershipCursor $next) use ($filter) {
                return $this->list($filter, $next);
            }, new UserGroupMembershipCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieve(UserGroupMembershipFilter $filter): ?UserGroupMembership
    {
        $this->logDebug("Retrieve for User group membership on adapter ");
        $span = $this->startSpan("Retrieve for User group membership on adapter");
        try {
            return $this->conn->retrieve($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function exists(UserGroupMembershipFilter $filter): bool
    {
        $this->logDebug("Exists for User group membership on adapter ");
        $span = $this->startSpan("Exists for User group membership on adapter");
        try {
            return $this->conn->exists($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function count(?UserGroupMembershipFilter $filter = null): int
    {
        $this->logDebug("Count for User group membership on adapter ");
        $span = $this->startSpan("Count for User group membership on adapter");
        try {
            return $this->conn->count($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneByUid(string $uid): ?UserGroupMembership
    {
        $this->logDebug("Find on by uid for User group membership on adapter");
        $span = $this->startSpan("Find on by uid for User group membership on adapter");
        try {
            return $this->conn->retrieve(new UserGroupMembershipFilter(uids: [$uid]));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
